 function burst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rnd(-120,120),vy:rnd(-150,50),life:rnd(.25,.65),color})}
 function update(dt){if(state!=='play'||paused)return;elapsed+=dt;if(dialogueTime>0){dialogueTime-=dt;if(dialogueTime<=0)$('#dialogue').classList.remove('show')}if(toastTime>0&&((toastTime-=dt)<=0))$('#toast').classList.remove('show');fireCooldown=Math.max(0,fireCooldown-dt);if(reload>0){reload-=dt;if(reload<=0){if(mode==='infantry'){let weap=weapons[weapon];let n=Math.min(weap.max, reserve);ammo=n;reserve=Math.max(0,reserve-n)}else ammo=12;showToast('RELOAD SELESAI')}updateHUD()}hitFlash=Math.max(0,hitFlash-dt);shake=Math.max(0,shake-dt*18);
 let move=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);if(mode!=='plane'){if(move)progress+=dt*(mode==='tank'?190:145)*move;progress=clamp(progress,0,MISSION);cam=progress;player.x=progress+230}else{if(keys.w||keys.arrowup)planeY-=240*dt;if(keys.s||keys.arrowdown)planeY+=240*dt;planeY=clamp(planeY,145,470);progress+=dt*210;cam=progress;}
 for(const b of dialogueBeats){if(progress/MISSION>=b.at&&dialogueIndex<dialogueBeats.indexOf(b)){showDialogue(dialogueBeats.indexOf(b));break}}
-if(Math.random()<dt*(mode==='plane'?1.5:1.1))enemySpawn();if(mode==='plane'&&Math.random()<dt*.55)enemies.push({x:cam+rnd(550,950),y:rnd(180,420),hp:42,max:42,kind:'flak',fire:rnd(2,4),walk:0,alive:true});enemyTimer-=dt;
+if(Math.random()<dt*(mode==='plane'?1.0:.58))enemySpawn();if(mode==='plane'&&Math.random()<dt*.55)enemies.push({x:cam+rnd(550,950),y:rnd(180,420),hp:42,max:42,kind:'flak',fire:rnd(2,4),walk:0,alive:true});enemyTimer-=dt;
 for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];if(!e.alive)continue;let gap=e.x-(cam+playerScreenX());if(mode==='plane'){e.x-=dt*80;if(e.kind!=='flak'&&gap<240&&gap>100&&Math.random()<dt*.3)damage(4)}else{e.x-=e.walk*dt;if(gap<510&&gap>80){e.fire-=dt;if(e.fire<=0){e.fire=rnd(1.6,3);if(Math.random()<(mode==='tank'?.24:.42))damage(mode==='tank'?3:7)}}}if(gap< -160){enemies.splice(i,1);continue}if(e.hp<=0){e.alive=false;kills++;burst((e.x-cam),e.y-20,'#dbad63',9);setTimeout(()=>{let ix=enemies.indexOf(e);if(ix>=0)enemies.splice(ix,1)},200)}}
 for(let i=shots.length-1;i>=0;i--){let s=shots[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;let hit=false;for(const e of enemies){if(!e.alive)continue;let ex=e.x-cam,ey=e.y-22;if(Math.hypot(s.x-ex,s.y-ey)<(e.kind==='heavy'?29:23)){e.hp-=s.damage;burst(ex,ey,'#e6c982',3);hit=true;if(e.hp<=0)burst(ex,ey,'#a85e3b',10);break}}if(hit||s.life<=0||s.x>w/scaleX+100||s.x<0)shots.splice(i,1)}
 for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=180*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}
 if(progress>=MISSION){end(true);return}if(Math.random()<dt*.014)damage(3);updateHUD()}

